import React from 'react';

import { useNavigate, useSearchParams } from 'react-router-dom';

import { addEquipModalAsync } from '@apps/Hiking/equip/HikingEquip/addEquip/addEduipModal';
import { previewEquipModal } from '@apps/Hiking/equip/HikingEquip/previewEquip/previewEduipModal';
import PageHeader from '@components/PageHeader';
import notificationHelper from '@helpers/notificationHelper';
import PohBreadcrumbs from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohContainer from '@ui-kit/layout/Container';

import EquipList from '../components/EquipList';

const EquipPage: React.FC = () => {
  const [actualKey, setActualKey] = React.useState('');

  const navigate = useNavigate();

  const [searchParams] = useSearchParams();

  return (
    <div>
      <PohBreadcrumbs data={[{ href: '/equip', text: 'Снаряжение', active: true }]} />

      <PohContainer>
        <PageHeader title="Снаряжение">
          <PohButton
            size={ButtonSize.Small}
            onClick={() => navigate(`/equip/backpacks`)}
            className="me-2"
          >
            Рюкзаки
          </PohButton>

          <PohButton
            size={ButtonSize.Small}
            onClick={() => navigate(`/equip/sets`)}
            className="me-2"
          >
            Сборки
          </PohButton>
          <PohButton
            variant={ButtonVariant.Success}
            size={ButtonSize.Small}
            onClick={async () => {
              const newItem = await addEquipModalAsync();
              notificationHelper.success('Добавлено');
              setActualKey(newItem.id.toString());
            }}
          >
            Добавить
          </PohButton>
        </PageHeader>
        <p className="mt-n3">
          <small>
            В этом списке будет отображается все снаряжение, которое по тем или иным причинам может
            оказаться в вашем рюкзаке
          </small>
        </p>
        <EquipList
          key={actualKey}
          showEmptyMessage
          criteria={searchParams ? Object.fromEntries(searchParams) : {}}
          onSelectEquipItem={(item, e) => {
            e.ctrlKey || e.altKey ? previewEquipModal(item) : navigate(`/equip/${item.id}`);
          }}
        />
      </PohContainer>
    </div>
  );
};

export default EquipPage;
